import { task, Queue } from "@trigger.dev/sdk";

const trialId = "multi_tenant_concurrency_control__PaijuUZ";

// Define a Queue with global concurrency limit of 10
const multiTenantQueue = new Queue({
  id: `multi-tenant-queue-${trialId}`,
  name: "Multi-tenant Queue",
  concurrencyLimit: 10,
});

interface MultiTenantPayload {
  userId: string;
  jobId: string;
}

// Define the task with per-user concurrency control
export const multiTenantTask = task({
  id: `multi-tenant-task-${trialId}`,
  name: "Multi-tenant Task",
  queue: multiTenantQueue,
  concurrencyKey: async (payload: MultiTenantPayload) => {
    // Limit concurrency to 1 per user
    return `user:${payload.userId}`;
  },
  run: async (payload: MultiTenantPayload, { ctx }) => {
    // Simulate work by sleeping for 5 seconds
    await new Promise((resolve) => setTimeout(resolve, 5000));

    return {
      userId: payload.userId,
      jobId: payload.jobId,
      startedAt: ctx.startedAt,
      finishedAt: ctx.finishedAt,
    };
  },
});

