import { multiTenantTask } from "../src/trigger/multi_tenant";

const client = new TriggerClient({
  id: "multi-tenant-task-client",
  apiKey: process.env.TRIGGER_API_KEY!,
  apiUrl: process.env.TRIGGER_API_URL,
});

async function main() {
  try {
    // Trigger 4 task instances in parallel
    const [runA1, runA2, runB1, runB2] = await Promise.all([
      multiTenantTask.trigger({ userId: "user_A", jobId: "A1" }),
      multiTenantTask.trigger({ userId: "user_A", jobId: "A2" }),
      multiTenantTask.trigger({ userId: "user_B", jobId: "B1" }),
      multiTenantTask.trigger({ userId: "user_B", jobId: "B2" }),
    ]);

    // Print the Run IDs in the required format
    console.log(`Run IDs: ${runA1.id}, ${runA2.id}, ${runB1.id}, ${runB2.id}`);
  } catch (error) {
    console.error("Error triggering tasks:", error);
    process.exit(1);
  }
}

main();

